INSERT INTO public."modules" ("id", "level_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('73778e22-777d-5fb6-8ef3-00746e69f978'::uuid, '417bcbcf-1354-516f-96af-7bbe5897bffb'::uuid, 0, 'Before You Trust the Answer', 'Northstar Retail has a GenAI-generated response ready for an internal demonstration, but the response has not been cleared, the approved source is not attached and review completion is not recorded. The learner must record one exact visible concern, identify the evidence checked and state what remains uncertain without diagnosing, correcting or approving the response.', '["Polished GenAI output may create pressure to act before evidence is complete", "unclear source or review status", "authority pressure"]'::jsonb, '["May treat generated output as approved evidence", "may convert uncertainty into fact", "may diagnose or correct outside L1 authority"]'::jsonb, 'Northstar Retail is preparing a GenAI customer-support assistant that answers customer questions using approved business information. A generated response appears polished and confident, but the supplied records may show conflict with an approved source, internal-use information appearing in customer-facing output, incomplete review evidence, unclear source or review status, and deadline pressure encouraging premature use. The learner must inspect supplied records, identify workflow objects, classify evidence, recognise visible quality, evidence and boundary signals, record uncertainty, organise a safe review handoff and prepare a permitted first review action without diagnosing the technical cause, changing the response, approving the output or closing the case.', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Recognise, classify, record and hand off supplied evidence."]'::jsonb, 'Use when Northstar Retail has a GenAI-generated response ready for an internal demonstration, but the response has not been cleared, the approved source is not attached and review completion is not recorded. The learner must record one exact visible concern, identify the evidence checked and state what remains uncertain without diagnosing, correcting or approving the response.', '{"major_concepts": "entry-evidence triage, exact observation, source-status checking, uncertainty recording, and role-boundary confirmation", "implementation_context_when_to_use": "Use when completing Before You Trust the Answer and producing the GenAI Workflow Entry Record within the learner''s L1 authority boundary", "reason_behind_concept": "Entry-level capability is demonstrated by accurate recognition, traceable evidence and safe escalation—not by changing, approving or diagnosing the workflow."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The GenAI Workflow Entry Record becomes the starting evidence object for workflow mapping."}'::jsonb, '{"technical_concepts_learnt": "Workflow objects, evidence status, claim classification, signal tagging, traceability, handoff records, authority boundaries, and A01-to-A02 revision evidence", "academic_refresher_concepts": "Observation, classification, evidence-based reasoning, uncertainty language, reflective learning, and transfer of learning"}'::jsonb, 'Northstar Retail has a GenAI-generated response ready for an internal demonstration, but the response has not been cleared, the approved source is not attached and review completion is not recorded. The learner must record one exact visible concern, identify the evidence checked and state what remains uncertain without diagnosing, correcting or approving the response.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Adobe Acrobat Reader", "ChatGPT Enterprise"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
