VALUES ('156b933d-f549-5fba-9b1b-797178d4b778'::uuid, '417bcbcf-1354-516f-96af-7bbe5897bffb'::uuid, 1, 'What Is Inside the Workflow?', 'The Workflow Owner cannot review the case efficiently because the supplied request, instruction, sources, output, status, observation and owner objects are not yet organised into a clear workflow structure. The learner must identify each object type, map its place and show confirmed, unconfirmed and review-layer relationships without inventing source use.', '["Polished GenAI output may create pressure to act before evidence is complete", "unclear source or review status", "authority pressure"]'::jsonb, '["May treat generated output as approved evidence", "may convert uncertainty into fact", "may diagnose or correct outside L1 authority"]'::jsonb, 'Northstar Retail is preparing a GenAI customer-support assistant that answers customer questions using approved business information. A generated response appears polished and confident, but the supplied records may show conflict with an approved source, internal-use information appearing in customer-facing output, incomplete review evidence, unclear source or review status, and deadline pressure encouraging premature use. The learner must inspect supplied records, identify workflow objects, classify evidence, recognise visible quality, evidence and boundary signals, record uncertainty, organise a safe review handoff and prepare a permitted first review action without diagnosing the technical cause, changing the response, approving the output or closing the case.', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Recognise, classify, record and hand off supplied evidence."]'::jsonb, 'Use when The Workflow Owner cannot review the case efficiently because the supplied request, instruction, sources, output, status, observation and owner objects are not yet organised into a clear workflow structure. The learner must identify each object type, map its place and show confirmed, unconfirmed and review-layer relationships without inventing source use.', '{"major_concepts": "workflow-object mapping, object-role labelling, confirmed versus unconfirmed relationships, source-connection caution, and owner handoff", "implementation_context_when_to_use": "Use when completing What Is Inside the Workflow? and producing the Annotated GenAI Workflow Map within the learner''s L1 authority boundary", "reason_behind_concept": "Entry-level capability is demonstrated by accurate recognition, traceable evidence and safe escalation—not by changing, approving or diagnosing the workflow."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Annotated GenAI Workflow Map supplies the object structure used for evidence classification."}'::jsonb, '{"technical_concepts_learnt": "Workflow objects, evidence status, claim classification, signal tagging, traceability, handoff records, authority boundaries, and A01-to-A02 revision evidence", "academic_refresher_concepts": "Observation, classification, evidence-based reasoning, uncertainty language, reflective learning, and transfer of learning"}'::jsonb, 'The Workflow Owner cannot review the case efficiently because the supplied request, instruction, sources, output, status, observation and owner objects are not yet organised into a clear workflow structure. The learner must identify each object type, map its place and show confirmed, unconfirmed and review-layer relationships without inventing source use.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Adobe Acrobat Reader", "ChatGPT Enterprise"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
