VALUES ('a5aefe99-2026-5a8b-976e-5b2d6387645f'::uuid, '02c85598-3f29-50f3-bdba-deea3d62de79'::uuid, 0, 'Before You Change the Workflow', 'The learner is moving from inspection to supported execution, but the sandbox includes editable fields, locked controls and actions that require owner approval. The learner must distinguish permitted supported tasks from prohibited production or governance actions before making any change.', '["Pressure to complete the workflow quickly", "mixed source status", "locked controls", "test deviations", "owner approval dependency"]'::jsonb, '["May treat support authority as independent design authority", "may use unapproved sources", "may alter locked controls", "may approve test results"]'::jsonb, 'Controlled GenAI workflow build and test support under evidence, version and owner controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the assigned L2 task for before you change the workflow", "use supplied procedures and evidence", "preserve version and authority controls", "escalate out-of-boundary items"]'::jsonb, 'Use when supporting a controlled GenAI workflow build or test in an approved sandbox under owner supervision.', '{"major_concepts": "sandbox-role readiness, editable-versus-locked control recognition, permitted-action mapping, escalation triggers, and execution-boundary proof", "implementation_context_when_to_use": "Use when completing Before You Change the Workflow and producing the L2 Readiness and Authority Record within the learner''s L2 authority boundary", "reason_behind_concept": "Supported application is proven when the learner follows approved procedures, preserves protected controls and produces reproducible evidence under supervision."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The L2 Readiness and Authority Record defines the controls used in every later supported workflow task."}'::jsonb, '{"technical_concepts_learnt": "Prompt components, source permissions, sandbox fields, configuration baselines, test cases, expected-versus-actual comparison, version logs, retest evidence, and escalation triggers", "academic_refresher_concepts": "Procedural learning, structured problem solving, controlled experimentation, documentation quality, feedback-driven revision, and professional communication"}'::jsonb, 'The learner is moving from inspection to supported execution, but the sandbox includes editable fields, locked controls and actions that require owner approval. The learner must distinguish permitted supported tasks from prohibited production or governance actions before making any change.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
