VALUES ('109a876c-5ca9-5265-a43b-abb3e032c840'::uuid, '02c85598-3f29-50f3-bdba-deea3d62de79'::uuid, 1, 'Translate the Workflow Request', 'The Workflow Owner supplies a business request that is incomplete, mixed with assumptions and not yet ready for workflow configuration. The learner must convert the request into structured requirements using approved prompts and templates while preserving unresolved items for owner clarification.', '["Pressure to complete the workflow quickly", "mixed source status", "locked controls", "test deviations", "owner approval dependency"]'::jsonb, '["May treat support authority as independent design authority", "may use unapproved sources", "may alter locked controls", "may approve test results"]'::jsonb, 'Controlled GenAI workflow build and test support under evidence, version and owner controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the assigned L2 task for translate the workflow request", "use supplied procedures and evidence", "preserve version and authority controls", "escalate out-of-boundary items"]'::jsonb, 'Use when supporting a controlled GenAI workflow build or test in an approved sandbox under owner supervision.', '{"major_concepts": "request decomposition, objective capture, user/input/output definition, constraint recording, missing-information control, and owner-question preparation", "implementation_context_when_to_use": "Use when completing Translate the Workflow Request and producing the Workflow Requirement Brief within the learner''s L2 authority boundary", "reason_behind_concept": "Supported application is proven when the learner follows approved procedures, preserves protected controls and produces reproducible evidence under supervision."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Workflow Requirement Brief becomes the approved input for prompt assembly."}'::jsonb, '{"technical_concepts_learnt": "Prompt components, source permissions, sandbox fields, configuration baselines, test cases, expected-versus-actual comparison, version logs, retest evidence, and escalation triggers", "academic_refresher_concepts": "Procedural learning, structured problem solving, controlled experimentation, documentation quality, feedback-driven revision, and professional communication"}'::jsonb, 'The Workflow Owner supplies a business request that is incomplete, mixed with assumptions and not yet ready for workflow configuration. The learner must convert the request into structured requirements using approved prompts and templates while preserving unresolved items for owner clarification.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
