VALUES ('0dabb64c-e17e-50e4-b85e-9ec7a776eddb'::uuid, '54eb917e-e5a9-5ebf-8c8d-cd8bac472907'::uuid, 5, 'Execute Tests and Resolve Routine Defects', 'The validation plan is approved, but the workflow produces routine defects that must be analysed and corrected within standard authority. The learner must execute tests, isolate routine issues, make controlled fixes and rerun affected tests.', '["Independent delivery pressure", "standard-pattern selection", "evidence completeness", "routine defect correction", "escalation judgement"]'::jsonb, '["May confuse independent routine authority with unrestricted authority", "may use unapproved sources", "may hide failed evidence", "may approve production release"]'::jsonb, 'Independent design and validation of a standard GenAI workflow under approved organisational patterns', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the independent L3 task for run tests and resolve routine defects", "use approved patterns and evidence", "preserve version and validation controls", "escalate non-routine items"]'::jsonb, 'Use when independently building and validating a standard GenAI workflow in an approved sandbox.', '{"major_concepts": "test execution, defect evidence, routine-versus-non-routine classification, controlled correction, retest, and escalation", "implementation_context_when_to_use": "Use when completing Execute Tests and Resolve Routine Defects and producing the Test Run and Routine Defect Resolution Log within the learner''s L3 authority boundary", "reason_behind_concept": "Independent capability is demonstrated by designing and validating standard workflows within approved patterns while escalating non-routine risk and release decisions."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Test Run and Routine Defect Resolution Log supplies the evidence used in final validation."}'::jsonb, '{"technical_concepts_learnt": "Acceptance criteria, prompt architecture, context filters, retrieval fallback, validation coverage, defect classification, controlled fixes, regression testing, and release-readiness evidence", "academic_refresher_concepts": "Systems thinking, requirements engineering, experimental design, root-cause reasoning within scope, evidence evaluation, and technical reporting"}'::jsonb, 'The validation plan is approved, but the workflow produces routine defects that must be analysed and corrected within standard authority. The learner must execute tests, isolate routine issues, make controlled fixes and rerun affected tests.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
