VALUES ('41b43074-f84f-5c75-929f-9979b16a8a0b'::uuid, '0899a455-1166-5d00-810d-8594e8c29ef9'::uuid, 0, 'Enter the Adaptive Designer Role', 'The learner must work in ambiguous and higher-complexity situations where several choices may be defensible. Before adapting the workflow, the learner must define decision authority, evidence expectations, trade-off responsibilities and escalation boundaries.', '["Ambiguous requirements", "competing constraints", "variable evidence quality", "trade-off pressure", "residual risk", "owner approval dependency"]'::jsonb, '["May treat ambiguity as authority", "may recommend without evidence", "may hide trade-offs", "may bypass governance or approval ownership"]'::jsonb, 'Adaptive GenAI workflow design under ambiguity, evidence, trade-off and governance controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the adaptive L4 task for enter the adaptive design role", "compare defensible options", "document trade-offs and residual risks", "preserve accountable ownership"]'::jsonb, 'Use when adapting an approved GenAI workflow for complex or ambiguous conditions.', '{"major_concepts": "adaptive-authority mapping, ambiguity-handling rules, trade-off responsibility, evidence thresholds, stakeholder ownership, and escalation boundaries", "implementation_context_when_to_use": "Use when completing Enter the Adaptive Designer Role and producing the Adaptive Authority and Ambiguity Readiness Record within the learner''s L4 authority boundary", "reason_behind_concept": "Adaptive capability is proven by making defensible choices under ambiguity, documenting trade-offs and residual risk, and preserving accountable approval boundaries."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Adaptive Authority and Ambiguity Readiness Record defines the judgement controls used in later adaptive work."}'::jsonb, '{"technical_concepts_learnt": "Ambiguity registers, option matrices, retrieval-risk controls, edge-case coverage, scenario comparison, confidence statements, residual-risk logs, and recommendation conditions", "academic_refresher_concepts": "Decision analysis, risk assessment, comparative evaluation, adaptive expertise, argumentation, stakeholder reasoning, and reflective judgement"}'::jsonb, 'The learner must work in ambiguous and higher-complexity situations where several choices may be defensible. Before adapting the workflow, the learner must define decision authority, evidence expectations, trade-off responsibilities and escalation boundaries.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
