VALUES ('d0e70b5a-b042-5fb0-ac23-fe7553b79c74'::uuid, '0899a455-1166-5d00-810d-8594e8c29ef9'::uuid, 1, 'Interpret an Ambiguous Workflow Change', 'The requested workflow change contains incomplete requirements, competing stakeholder expectations and unresolved assumptions. The learner must frame the problem, separate confirmed requirements from interpretation and identify decisions that require stakeholder confirmation.', '["Ambiguous requirements", "competing constraints", "variable evidence quality", "trade-off pressure", "residual risk", "owner approval dependency"]'::jsonb, '["May treat ambiguity as authority", "may recommend without evidence", "may hide trade-offs", "may bypass governance or approval ownership"]'::jsonb, 'Adaptive GenAI workflow design under ambiguity, evidence, trade-off and governance controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the adaptive L4 task for interpret an ambiguous workflow change request", "compare defensible options", "document trade-offs and residual risks", "preserve accountable ownership"]'::jsonb, 'Use when adapting an approved GenAI workflow for complex or ambiguous conditions.', '{"major_concepts": "confirmed-versus-ambiguous separation, assumption logging, competing-constraint analysis, stakeholder questions, and controlled problem framing", "implementation_context_when_to_use": "Use when completing Interpret an Ambiguous Workflow Change and producing the Ambiguous Workflow Change Interpretation Brief within the learner''s L4 authority boundary", "reason_behind_concept": "Adaptive capability is proven by making defensible choices under ambiguity, documenting trade-offs and residual risk, and preserving accountable approval boundaries."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Ambiguous Workflow Change Interpretation Brief becomes the basis for comparing design options."}'::jsonb, '{"technical_concepts_learnt": "Ambiguity registers, option matrices, retrieval-risk controls, edge-case coverage, scenario comparison, confidence statements, residual-risk logs, and recommendation conditions", "academic_refresher_concepts": "Decision analysis, risk assessment, comparative evaluation, adaptive expertise, argumentation, stakeholder reasoning, and reflective judgement"}'::jsonb, 'The requested workflow change contains incomplete requirements, competing stakeholder expectations and unresolved assumptions. The learner must frame the problem, separate confirmed requirements from interpretation and identify decisions that require stakeholder confirmation.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
