VALUES ('bb08a096-4d57-5ca8-b85f-859ed8c81269'::uuid, '0899a455-1166-5d00-810d-8594e8c29ef9'::uuid, 2, 'Compare Adaptive Prompt and Workflow Options', 'No single prompt or workflow design is obviously correct for the ambiguous request. The learner must generate and compare viable options using evidence, trade-offs, constraints and residual risk.', '["Ambiguous requirements", "competing constraints", "variable evidence quality", "trade-off pressure", "residual risk", "owner approval dependency"]'::jsonb, '["May treat ambiguity as authority", "may recommend without evidence", "may hide trade-offs", "may bypass governance or approval ownership"]'::jsonb, 'Adaptive GenAI workflow design under ambiguity, evidence, trade-off and governance controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the adaptive L4 task for compare prompt and workflow design options", "compare defensible options", "document trade-offs and residual risks", "preserve accountable ownership"]'::jsonb, 'Use when adapting an approved GenAI workflow for complex or ambiguous conditions.', '{"major_concepts": "option generation, evidence-based comparison, benefit and constraint analysis, reversibility, risk, test implications, and recommendation rationale", "implementation_context_when_to_use": "Use when completing Compare Adaptive Prompt and Workflow Options and producing the Adaptive Prompt and Workflow Option Comparison Matrix within the learner''s L4 authority boundary", "reason_behind_concept": "Adaptive capability is proven by making defensible choices under ambiguity, documenting trade-offs and residual risk, and preserving accountable approval boundaries."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Adaptive Prompt and Workflow Option Comparison Matrix identifies the preferred option for context adaptation and testing."}'::jsonb, '{"technical_concepts_learnt": "Ambiguity registers, option matrices, retrieval-risk controls, edge-case coverage, scenario comparison, confidence statements, residual-risk logs, and recommendation conditions", "academic_refresher_concepts": "Decision analysis, risk assessment, comparative evaluation, adaptive expertise, argumentation, stakeholder reasoning, and reflective judgement"}'::jsonb, 'No single prompt or workflow design is obviously correct for the ambiguous request. The learner must generate and compare viable options using evidence, trade-offs, constraints and residual risk.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
