VALUES ('7a9d039d-b034-5957-9755-09b12391e22c'::uuid, '0899a455-1166-5d00-810d-8594e8c29ef9'::uuid, 3, 'Adapt Context and Retrieval Controls', 'The complex use case requires context changes, but broader retrieval may increase leakage, ambiguity or unsupported-output risk. The learner must adapt context strategy while preserving access, relevance and boundary controls.', '["Ambiguous requirements", "competing constraints", "variable evidence quality", "trade-off pressure", "residual risk", "owner approval dependency"]'::jsonb, '["May treat ambiguity as authority", "may recommend without evidence", "may hide trade-offs", "may bypass governance or approval ownership"]'::jsonb, 'Adaptive GenAI workflow design under ambiguity, evidence, trade-off and governance controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the adaptive L4 task for adapt source and retrieval context safely", "compare defensible options", "document trade-offs and residual risks", "preserve accountable ownership"]'::jsonb, 'Use when adapting an approved GenAI workflow for complex or ambiguous conditions.', '{"major_concepts": "context-change design, source eligibility, retrieval trade-offs, leakage risk, relevance risk, safeguards, and residual uncertainty", "implementation_context_when_to_use": "Use when completing Adapt Context and Retrieval Controls and producing the Context Adaptation and Retrieval Risk Record within the learner''s L4 authority boundary", "reason_behind_concept": "Adaptive capability is proven by making defensible choices under ambiguity, documenting trade-offs and residual risk, and preserving accountable approval boundaries."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Context Adaptation and Retrieval Risk Record defines the risks and safeguards that adaptive test coverage must verify."}'::jsonb, '{"technical_concepts_learnt": "Ambiguity registers, option matrices, retrieval-risk controls, edge-case coverage, scenario comparison, confidence statements, residual-risk logs, and recommendation conditions", "academic_refresher_concepts": "Decision analysis, risk assessment, comparative evaluation, adaptive expertise, argumentation, stakeholder reasoning, and reflective judgement"}'::jsonb, 'The complex use case requires context changes, but broader retrieval may increase leakage, ambiguity or unsupported-output risk. The learner must adapt context strategy while preserving access, relevance and boundary controls.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
