VALUES ('d761ee0f-353e-5caf-8982-18027a18bdfb'::uuid, '0899a455-1166-5d00-810d-8594e8c29ef9'::uuid, 4, 'Design Adaptive Test Coverage', 'Standard test cases do not sufficiently cover the workflow’s new ambiguity, edge cases and competing constraints. The learner must design expanded coverage that tests alternatives, failure modes and residual risks.', '["Ambiguous requirements", "competing constraints", "variable evidence quality", "trade-off pressure", "residual risk", "owner approval dependency"]'::jsonb, '["May treat ambiguity as authority", "may recommend without evidence", "may hide trade-offs", "may bypass governance or approval ownership"]'::jsonb, 'Adaptive GenAI workflow design under ambiguity, evidence, trade-off and governance controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the adaptive L4 task for design adaptive test coverage", "compare defensible options", "document trade-offs and residual risks", "preserve accountable ownership"]'::jsonb, 'Use when adapting an approved GenAI workflow for complex or ambiguous conditions.', '{"major_concepts": "scenario-family design, edge-case coverage, competing-constraint tests, boundary tests, risk-based prioritisation, and coverage limits", "implementation_context_when_to_use": "Use when completing Design Adaptive Test Coverage and producing the Adaptive Workflow Test Coverage Plan within the learner''s L4 authority boundary", "reason_behind_concept": "Adaptive capability is proven by making defensible choices under ambiguity, documenting trade-offs and residual risk, and preserving accountable approval boundaries."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Adaptive Workflow Test Coverage Plan becomes the evidence-generation framework for complex test evaluation."}'::jsonb, '{"technical_concepts_learnt": "Ambiguity registers, option matrices, retrieval-risk controls, edge-case coverage, scenario comparison, confidence statements, residual-risk logs, and recommendation conditions", "academic_refresher_concepts": "Decision analysis, risk assessment, comparative evaluation, adaptive expertise, argumentation, stakeholder reasoning, and reflective judgement"}'::jsonb, 'Standard test cases do not sufficiently cover the workflow’s new ambiguity, edge cases and competing constraints. The learner must design expanded coverage that tests alternatives, failure modes and residual risks.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
