VALUES ('65a517ea-f114-5f9e-9b50-fc7944d795c2'::uuid, '0899a455-1166-5d00-810d-8594e8c29ef9'::uuid, 5, 'Evaluate Complex Test Evidence', 'The adaptive workflow produces mixed results across scenarios. The learner must evaluate conflicting evidence, compare options, distinguish acceptable trade-offs from unresolved risk and determine what recommendation the evidence supports.', '["Ambiguous requirements", "competing constraints", "variable evidence quality", "trade-off pressure", "residual risk", "owner approval dependency"]'::jsonb, '["May treat ambiguity as authority", "may recommend without evidence", "may hide trade-offs", "may bypass governance or approval ownership"]'::jsonb, 'Adaptive GenAI workflow design under ambiguity, evidence, trade-off and governance controls', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Perform the adaptive L4 task for evaluate test evidence and select an adaptive response", "compare defensible options", "document trade-offs and residual risks", "preserve accountable ownership"]'::jsonb, 'Use when adapting an approved GenAI workflow for complex or ambiguous conditions.', '{"major_concepts": "mixed-result evaluation, conflicting-evidence comparison, confidence judgement, acceptable trade-off analysis, residual risk, and recommendation implications", "implementation_context_when_to_use": "Use when completing Evaluate Complex Test Evidence and producing the Adaptive Test Evidence Evaluation Record within the learner''s L4 authority boundary", "reason_behind_concept": "Adaptive capability is proven by making defensible choices under ambiguity, documenting trade-offs and residual risk, and preserving accountable approval boundaries."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Adaptive Test Evidence Evaluation Record supplies the evidence base for the final adaptive design recommendation."}'::jsonb, '{"technical_concepts_learnt": "Ambiguity registers, option matrices, retrieval-risk controls, edge-case coverage, scenario comparison, confidence statements, residual-risk logs, and recommendation conditions", "academic_refresher_concepts": "Decision analysis, risk assessment, comparative evaluation, adaptive expertise, argumentation, stakeholder reasoning, and reflective judgement"}'::jsonb, 'The adaptive workflow produces mixed results across scenarios. The learner must evaluate conflicting evidence, compare options, distinguish acceptable trade-offs from unresolved risk and determine what recommendation the evidence supports.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "ChatGPT Enterprise sandbox", "Microsoft SharePoint", "Microsoft Edge"]}'::jsonb, TRUE, TRUE)
