VALUES ('a5623658-7c1c-579b-ab3b-fc5a9b9cc4f2'::uuid, '3aa64007-0085-5217-9951-c1f64ff9ee7c'::uuid, 0, 'Enter the Practice-Leadership Role', 'The learner is moving from solving individual workflow problems to shaping standards and practice across teams. The learner must define governance authority, accountable ownership, evidence expectations and limits on leadership decisions.', '["Inconsistent practices", "cross-team variation", "fragmented governance", "repeated defects", "reviewer calibration gaps", "scale pressure", "accountable ownership"]'::jsonb, '["May over-standardise legitimate variation", "may treat leadership as approval authority", "may infer root cause without evidence", "may design controls without owners or adoption evidence"]'::jsonb, 'Organisation-wide GenAI workflow design governance, reusable practice standards and capability improvement', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Lead the L5 task for enter the practice-leadership role", "use cross-workflow evidence", "define reusable and governed practice", "preserve accountable ownership"]'::jsonb, 'Use when standardising, governing or scaling GenAI workflow design practice across teams.', '{"major_concepts": "practice-lead authority, governance responsibility, accountable ownership, consultation duties, evidence expectations, and non-delegable approvals", "implementation_context_when_to_use": "Use when completing Enter the Practice-Leadership Role and producing the Leadership Authority and Governance Readiness Record within the learner''s L5 authority boundary", "reason_behind_concept": "Expert capability is demonstrated by improving practice across multiple workflows through standards, governance, capability building and measurable evidence—not by solving only one case."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The Leadership Authority and Governance Readiness Record defines the governance boundary for all subsequent practice-lead work."}'::jsonb, '{"technical_concepts_learnt": "Governance models, control plans, standards architecture, pattern-library metadata, cross-workflow analysis, reviewer calibration, coaching evidence, adoption metrics, and review cadence", "academic_refresher_concepts": "Organisational learning, governance design, quality assurance, systems analysis, coaching theory, change management, and strategic communication"}'::jsonb, 'The learner is moving from solving individual workflow problems to shaping standards and practice across teams. The learner must define governance authority, accountable ownership, evidence expectations and limits on leadership decisions.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "Microsoft SharePoint", "ChatGPT Enterprise", "Microsoft Teams"]}'::jsonb, TRUE, TRUE)
