VALUES ('605bae8c-a5ed-56b5-86eb-1d6ff60d047e'::uuid, '3aa64007-0085-5217-9951-c1f64ff9ee7c'::uuid, 1, 'Define the GenAI Workflow Design Standard', 'Teams use inconsistent methods for workflow objectives, prompt structure, context controls, testing, evidence and handoff. The learner must define a standard that improves consistency without erasing legitimate variation.', '["Inconsistent practices", "cross-team variation", "fragmented governance", "repeated defects", "reviewer calibration gaps", "scale pressure", "accountable ownership"]'::jsonb, '["May over-standardise legitimate variation", "may treat leadership as approval authority", "may infer root cause without evidence", "may design controls without owners or adoption evidence"]'::jsonb, 'Organisation-wide GenAI workflow design governance, reusable practice standards and capability improvement', '["Completion of the previous module artifact where applicable"]'::jsonb, '["Lead the L5 task for define the genai workflow design standard", "use cross-workflow evidence", "define reusable and governed practice", "preserve accountable ownership"]'::jsonb, 'Use when standardising, governing or scaling GenAI workflow design practice across teams.', '{"major_concepts": "standard scope, mandatory design elements, minimum controls, validation expectations, exception handling, ownership, and review cadence", "implementation_context_when_to_use": "Use when completing Define the GenAI Workflow Design Standard and producing the GenAI Workflow Design Standard within the learner''s L5 authority boundary", "reason_behind_concept": "Expert capability is demonstrated by improving practice across multiple workflows through standards, governance, capability building and measurable evidence—not by solving only one case."}'::jsonb, '{"ai_support_tips": "After completing the human-first attempt, use the approved AI assistant to check missing evidence links, unclear reasoning, weak boundary wording, incomplete traceability, and revision quality; AI must not create missing evidence, make accountable decisions, bypass controls, or approve release", "module_continuity_link": "The GenAI Workflow Design Standard becomes the governing reference for pattern, evaluation and coaching work."}'::jsonb, '{"technical_concepts_learnt": "Governance models, control plans, standards architecture, pattern-library metadata, cross-workflow analysis, reviewer calibration, coaching evidence, adoption metrics, and review cadence", "academic_refresher_concepts": "Organisational learning, governance design, quality assurance, systems analysis, coaching theory, change management, and strategic communication"}'::jsonb, 'Teams use inconsistent methods for workflow objectives, prompt structure, context controls, testing, evidence and handoff. The learner must define a standard that improves consistency without erasing legitimate variation.', '{"items": ["Microsoft Excel", "Microsoft PowerPoint", "Microsoft Word", "Microsoft SharePoint", "ChatGPT Enterprise", "Microsoft Teams"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
